# Step 1: Get the customer_id for "Dayana Robel"
dayana_customer_id = customer.WHERE(
    customer_name == "Dayana Robel"
).SINGULAR().customer_id

# Step 2: Count the policies linked to this customer_id
total_policies_dayana = customers_policy.WHERE(
    customer_id == dayana_customer_id
).CALCULATE(
    policy_count=COUNT()
).SINGULAR().policy_count

total_products_purchased = GRAPH.CALCULATE(
    total_quantity=SUM(
        order_item.WHERE(
            order_item.customer_order.order_date < '2018-03-17 07:13:53'
        ).CALCULATE(
            # Convert order_quantity to an integer before summing
            quantity_as_int=INT(order_quantity)
        ).quantity_as_int
    )
)

total_products_ordered_before_timestamp = GRAPH.CALCULATE(
    total_amount=SUM(
        TO_NUMBER(
            Customer_Orders.WHERE(
                Customer_Orders.order_date < DATETIME('2018-03-17 07:13:53')
            ).Order_Items.order_quantity
        )
    )
)

total_money_requested_tall_entrepreneurs = GRAPH.CALCULATE(
    total_money_requested=SUM(peoples.WHERE(height > 1.85).entrepreneurs.money_requested)
)

num_highschoolers_in_grades_9_or_10 = highschoolers.WHERE(
    (highschoolers.grade == 9) | (highschoolers.grade == 10)
).CALCULATE(
    count_of_highschoolers=COUNT(highschoolers.id)
)
num_highschoolers_in_grades_9_or_10

result = Project_Staff.WHERE(
    (role_code == 'leader') | (date_from < DATETIME('1989-04-24 23:51:54'))
).CALCULATE(
    number_of_project_members=COUNT()
)

qualified_cities = cities.WHERE(
    (temperatures.Feb > temperatures.Jun) | (HAS(hosting_cities))
).CALCULATE(
    city_name=city
)

teacher_name_for_math = course_arrange.WHERE(
    course.Course == 'Math'
).CALCULATE(
    teacher_name=teacher.Name
)

most_highschoolers_grade = highschoolers.PARTITION(
    name="grades_by_count",
    by=grade
).CALCULATE(
    student_grade=grade,
    count_of_students=COUNT(highschoolers)
).TOP_K(1, by=count_of_students.DESC()).CALCULATE(
    grade=student_grade
)

london_employees_info = hr_1.employee.WHERE(
    employee.department.location.CITY == 'London'
).CALCULATE(
    full_name=JOIN_STRINGS(' ', first_name, last_name),
    employee_salary=salary
)

nominated_songs = music_festival.WHERE(
